def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    dangerous_prev = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                bid = float(bid)
                prev_bids.append(bid)
                if opp.get('budget', 0) > 0:
                    dangerous_prev.append(bid)

    if not alive:
        base = DAILY_SALARY * 0.18
        if no_water_days >= 2 or hp <= 2:
            base = DAILY_SALARY * 0.55
        return max(0.0, min(budget, round(base, 2)))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    highest_danger = max(dangerous_prev) if dangerous_prev else highest_prev

    tight_supply = supply <= 17
    medium_supply = supply <= 20
    urgent = (no_water_days >= 2) or (hp <= 2)
    pressured = (no_water_days >= 1) or (hp <= 4)

    target = 0.0

    if urgent:
        if highest_danger >= 140:
            target = highest_danger * 0.72
        elif highest_danger >= 80:
            target = highest_danger + 3.0
        else:
            target = DAILY_SALARY * 0.95
    elif tight_supply:
        if highest_danger >= 150:
            target = DAILY_SALARY * 0.52
        elif highest_danger >= 90:
            target = min(DAILY_SALARY * 0.9, highest_danger + 2.0)
        elif highest_danger > 0:
            target = max(DAILY_SALARY * 0.58, highest_danger + 1.5)
        else:
            target = DAILY_SALARY * 0.6
    elif medium_supply:
        if pressured:
            if highest_danger >= 120:
                target = DAILY_SALARY * 0.5
            elif highest_danger > 0:
                target = max(DAILY_SALARY * 0.45, highest_danger + 1.0)
            else:
                target = DAILY_SALARY * 0.48
        else:
            if highest_danger >= 120:
                target = DAILY_SALARY * 0.22
            elif highest_danger >= 70:
                target = DAILY_SALARY * 0.34
            else:
                target = DAILY_SALARY * 0.4
    else:
        if pressured:
            if highest_danger >= 100:
                target = DAILY_SALARY * 0.42
            elif highest_danger > 0:
                target = max(DAILY_SALARY * 0.36, highest_danger * 0.9)
            else:
                target = DAILY_SALARY * 0.38
        else:
            target = DAILY_SALARY * 0.2

    rich_threats = 0
    for opp in alive:
        if float(opp.get('budget', 0)) >= 140:
            rich_threats += 1
    if rich_threats >= 2 and not urgent and not tight_supply:
        target *= 0.92

    if day >= 8 and hp > 4 and no_water_days == 0:
        target *= 0.9

    target = max(0.0, min(budget, target))
    return round(target, 2)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append((opp_id, opp))

    # If no opponents are alive, bid to secure water cheaply.
    if not alive_opponents:
        return max(0.0, min(float(my_status['budget']), DAILY_SALARY * 0.4))

    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])

    # Use only yesterday's immediate bid pressure from traces.
    prev_bids = []
    for _, opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Estimate how contested the market was yesterday.
    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Determine our target bid fraction.
    # Cindy-like behavior suggests others bid aggressively; we counter with a near-top bid.
    # If our HP is low, we must secure water.
    # Supply affects likelihood of needing to win: lower supply => more competitive.
    supply_ratio = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY != MIN_SUPPLY else 0.5
    supply_ratio = max(0.0, min(1.0, supply_ratio))
    # Lower supply -> higher competition.
    competition = 1.0 - supply_ratio

    if my_hp <= 2.0:
        # Emergency: bid to win.
        base = DAILY_SALARY * (0.85 + 0.1 * competition)
    elif my_hp <= 4.0:
        base = DAILY_SALARY * (0.65 + 0.15 * competition)
    else:
        base = DAILY_SALARY * (0.50 + 0.10 * competition)

    # If yesterday someone bid very high, we raise our bid slightly above the likely leader.
    # Otherwise, bid around our base.
    if highest_prev_bid >= DAILY_SALARY * 0.8:
        target = max(base, highest_prev_bid * 0.98)
    elif highest_prev_bid >= DAILY_SALARY * 0.55:
        target = max(base, highest_prev_bid * 0.88)
    else:
        # If others were weak, don't overpay.
        target = base

    # Convert target into a conservative final bid within budget.
    # Also cap by daily salary to avoid pathological overbidding.
    cap = min(my_budget, DAILY_SALARY * 1.05)
    bid = min(cap, target)

    # Ensure non-negative.
    if bid < 0.0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # If no opponents, bid minimum to conserve budget
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    # Calculate days left to manage budget
    days_left = EPISODE_DAYS - day_context['day'] + 1

    # Collect yesterday's bids from active opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    highest_prev_bid = 0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    # Base bid strategy
    # If HP is critical or no water days accumulating, bid aggressively
    if my_status['hp'] <= 2 or my_status['no_water_days'] >= 1:
        # Desperate for water, bid high
        bid = DAILY_SALARY * 0.95 
        if highest_prev_bid > 0:
            bid = max(bid, highest_prev_bid + 5) 
    else:
        # HP is healthy, can be more strategic
        # If it's late in the game, increase aggression
        if day_context['day'] >= EPISODE_DAYS - 2: # Last 2 days
            bid = DAILY_SALARY * 0.8 
            if highest_prev_bid > 0:
                bid = max(bid, highest_prev_bid + 2) 
        else:
            # Early to mid-game, balance conservation and competition
            if highest_prev_bid > 0:
                if highest_prev_bid > DAILY_SALARY * 1.0: # Opponent bid very high (like Alex's max bid history)
                    # If my budget is tight, I might not compete at this level
                    if my_status['budget'] / days_left < DAILY_SALARY * 0.8: 
                        bid = DAILY_SALARY * 0.5 
                    else:
                        bid = highest_prev_bid + 1 
                else: # Moderate highest_prev_bid
                    bid = max(DAILY_SALARY * 0.6, highest_prev_bid + 5) 
            else:
                # No previous bids, or all were 0. Bid a reasonable amount.
                bid = DAILY_SALARY * 0.6 

    # Ensure bid does not exceed available budget
    final_bid = min(my_status['budget'], bid)

    # Ensure bid is at least 1 if budget allows, to signal intent
    if final_bid == 0 and my_status['budget'] > 0:
        final_bid = 1

    return final_bid
